import { ReactElement } from "react";
import { getTranslationFn } from "../App";

export type LanguageSelectorInput = {
  curLang: string
  onChange?: (lang: string) => void
  getTranslation: getTranslationFn
}

const languages = ['en', 'es', 'pt']

export default function LanguageSelector({ curLang, onChange, getTranslation }: LanguageSelectorInput): ReactElement {
  let menu_options: ReactElement[] = []

  const onMenuClicked = (el: EventTarget) => {
    if (!onChange) return;

    const newLang = (el as HTMLElement).dataset.lang || '';

    onChange(newLang)
  }

  languages.forEach(lang => {
    const langTranslation = getTranslation('lang_' + lang)
    menu_options.push(
      <li key={lang} data-lang={lang} className={lang === curLang ? 'active' : ''}>
        <label data-lang={lang}>{ `${langTranslation} (${lang.toUpperCase()})` }</label>
      </li>
    )
  })

  return <div>
    <button>
      <span>{getTranslation('lang_' + curLang)}</span>
      <i>language</i>
    </button>
    <menu onClick={(it) => onMenuClicked(it.target)}>
      { menu_options }
    </menu>
  </div>
}
