import "beercss"
import "material-dynamic-colors"
import './App.css'

import StepsBar from './components/steps-bar';
import Question from './components/question';
import Data from './data/data.json'
import TestState from './data/test-state-a.json'
import { ReactElement, useEffect, useState } from 'react';
import DebugBar from './components/debug-bar';

import { FeedbackSectionEnum, type AnswerStateIndexType, type AnwersStateType, type SectionStateType } from './App.types';
import Feedback from './components/feedback';
import LanguageSelector from './components/language';
import Welcome from './components/welcome';
import { IngestedDataType } from './ingest/ingest.types';

export type getTranslationFn = (key: string) => string;



function App() {
  // Ability to tweak template's main color style
  // useEffect(() => {
  //   ui("theme", "#d211e0")
  // }, [])

  const queryParams = new URLSearchParams(window.location.search)

  const getTranslation = (key: string): string => {
    // @ts-ignore
    if (!Data.translation[key]) {
      return '🛑' + key;
    }

    // @ts-ignore
    return Data.translation[key][language];
  }

  const [sectionState, setSectionState] = useState<SectionStateType>({
    current: 1,
    locked: 0,
    feedback: 0,
    feedbackReadAll: false,
  })
  const [answersState, setAnswersState] = useState<AnwersStateType>({
    question_answers: {},
    answers_index: {},
  })
  const [isWelcome, setIsWelcome] = useState<boolean>(() => {
    if (queryParams.has('skipWelcome')) {
      return false;
    }
    return true;
  })

  // DEBUG CODE - REMOVE LATER ---------------------------------------------------
  // const [sectionState, setSectionState] = useState<SectionStateType>({ current: 6, locked: 5, feedback: FeedbackSectionEnum.SCORES, feedbackReadAll: false })
  // const [answersState, setAnswersState] = useState<AnwersStateType>(TestState)
  // DEBUG CODE - REMOVE LATER ---------------------------------------------------

  const [language, setLanguage] = useState<string>(() => {
    const locale = new Intl.Locale(navigator.language || 'en-us');
    let lang = locale.language

    if (queryParams.has('lang')) {
      lang = queryParams.get('lang') || locale.language
    }

    switch (lang) {
      case 'en':
      case 'pt':
      case 'es':
        return lang;
      default:
        return 'en';
    }
  })
  const [isDebug] = useState<boolean>(() => {
    return queryParams.has('debug');
  })


  const onValueChange = (question_id: string, selectedValue: string, isMulti: boolean, checked: boolean) => {
    // console.log(`Question [${question_id}] sel. value [${selectedValue}] isMulti? [${isMulti}] checked? [${checked}]`);

    if (!isMulti) {
      // Mark all options as undefined (not selected)
      let all_empty_answers: AnswerStateIndexType = {};
      Data.questions
        .find(it => it.id === question_id)
        ?.answers.forEach(answer => {
          all_empty_answers[answer.id] = undefined;
        });


      // Exception: when we change the first question, clear all responses that there might be
      if (question_id === 'A0') {
        setAnswersState({
          question_answers: {
            [question_id]: [selectedValue],
          },
          answers_index: {
            [selectedValue]: true,
          }
        })

        return;
      }


      setAnswersState({
        question_answers: {
          ... answersState.question_answers,
          [question_id]: [selectedValue],
        },
        answers_index: {
          ... answersState.answers_index,
          ... all_empty_answers,
          // Mark the last selected option
          [selectedValue]: true,
        }
      })
    }
    else {
      // When multi-choice, we store a string[] with all the currently selected Answer_IDs
      let current_answers: string[] = answersState.question_answers[question_id] || [];

      if (checked) {
        // If we are selecting it, add it to the list
        current_answers.push(selectedValue)
      }
      else {
        // If we are de-selecting it, remove it from the list
        const idx = current_answers.indexOf(selectedValue);
        if (idx >= 0) {
          current_answers.splice(idx, 1) // Splice affects the array
        }
      }

      setAnswersState({
        question_answers: {
          ... answersState.question_answers,
          [question_id]: current_answers,
        },
        answers_index: {
          ... answersState.answers_index,
          [selectedValue]: checked ? true : undefined,
        }
      })
    }
  }

  const onNextStepClicked = () => {
    window.scrollTo({top: 0});

    const newSection = sectionState.current + 1
    setSectionState({
      ...sectionState,
      current: newSection,
      locked: Math.max(sectionState.current, sectionState.locked),
    })
  }

  const onPrevStepClicked = () => {
    window.scrollTo({top: 0});

    const newSection = sectionState.current - 1
    setSectionState({
      ...sectionState,
      current: newSection,
    })
  }

  const onGoToFirstStepClicked = () => {
    window.scrollTo({top: 0});
    setSectionState({
      ...sectionState,
      current: 1,
      feedback: FeedbackSectionEnum.SCORES,
      feedbackReadAll: false,
    })
  }

  const onGotToStepClicked = (index: number) => {
    window.scrollTo({top: 0});
    setSectionState({
      ...sectionState,
      current: index,
      feedback: FeedbackSectionEnum.SCORES,
      feedbackReadAll: false,
    })
  }

  const onFeedbackSectionChanged = (target: number, hasMoreFeedback: boolean) => {
    window.scrollTo({top: 0});

    setSectionState({
      ...sectionState,
      feedback: target,
      feedbackReadAll: !hasMoreFeedback ? true : sectionState.feedbackReadAll,
    })
  }

  const showQuestionsPage = () => {
    const filtered_questions = Data.questions
    .filter(it => it.section === sectionState.current)
    .filter(it => !it.filter ? true : answersState.answers_index[it.filter]);

    // Check if all questions in the current section have been answered
    let all_question_answered = true;
    for (let i = 0 ; i < filtered_questions.length ; i++ ) {
      const question_id = filtered_questions[i].id;

      if (!answersState.question_answers[question_id] || answersState.question_answers[question_id].length === 0) {
        all_question_answered = false;
        break;
      }
    }

    const filtered_questions_html = filtered_questions.map((it: any) => {
      return <Question
        key={it.id}
        question={it}
        onChange={onValueChange}
        values={answersState.question_answers[it.id]}
        isDebug={isDebug}
        getTranslation={getTranslation}
        sectionState={sectionState}
        answersIndex={answersState.answers_index}></Question>
    })

    const isFirstPage = sectionState.current === 1

    return <>
      <StepsBar
        sectionState={sectionState}
        maxSections={Data.sections_amount}
        isDebug={isDebug}
        getTranslation={getTranslation}
        onClick={onGotToStepClicked} />

      { filtered_questions_html }

      {/* Mobile view */}
      <div className="s grid">
        <button className="s12 large small-round" disabled={ !all_question_answered } onClick={onNextStepClicked}>
          { getTranslation('web_btn_next_step') }
          <i>chevron_right</i>
        </button>
        <button className="s12 large small-round border secondary-border secondary-text" disabled={isFirstPage} onClick={onPrevStepClicked}>
          <i>chevron_left</i>
          { getTranslation('web_btn_prev_step') }
        </button>
      </div>

      {/* Desktop view */}
      <nav className="m l center-align large-space">
        <button className="large border secondary-border secondary-text left-round" disabled={isFirstPage} onClick={onPrevStepClicked}>
          <i>chevron_left</i>
          { getTranslation('web_btn_prev_step') }
        </button>
        <button className="large right-round" disabled={ !all_question_answered } onClick={onNextStepClicked}>
          { getTranslation('web_btn_next_step') }
          <i>chevron_right</i>
        </button>
      </nav>
    </>
  }

  const onLanguageChange = (lang: string) => {
    setLanguage(lang);
  }

  const onSkipWelcome = () => {
    setIsWelcome(false);
  }

  // change the title of the window tab to match the selected lang
  document.title = getTranslation('tab_title')

  // ------------------------------------------------------------------------------------------------------------------------------
  // Main body
  const result_section_idx = Data.sections_amount + 1;
  let body: ReactElement = <></>

  if (isWelcome) {
    body = <Welcome
      getTranslation={getTranslation}
      data={Data as IngestedDataType}
      onClick={onSkipWelcome}
      language={language}
      onLangSelected={onLanguageChange} />
  }
  else if (sectionState.current === result_section_idx) {

    body = <>
      <StepsBar
        sectionState={sectionState}
        maxSections={Data.sections_amount}
        isDebug={isDebug}
        getTranslation={getTranslation}
        onClick={onGotToStepClicked} />

      { /* @ts-ignore */ }
      <Feedback data={Data}
        isDebug={isDebug}
        answersState={answersState}
        sectionState={sectionState}
        getTranslation={getTranslation}
        goToFirstStepClicked={onGoToFirstStepClicked}
        onFeedbackSectionChange={onFeedbackSectionChanged}
        language={language} />
    </>
  }
  else if (sectionState.current < result_section_idx) {
    body = showQuestionsPage();
  }


  return <>
    <DebugBar isDebug={isDebug} currentSection={sectionState.current} answersState={answersState} />
    <header className="fill">
      <nav>
        <h6 className="max left-align s small-text">{getTranslation(isWelcome ? 'welcome_title' : 'main_title')}</h6>
        <h6 className="max center-align m l">{getTranslation(isWelcome ? 'welcome_title' : 'main_title')}</h6>

        <LanguageSelector curLang={language} onChange={onLanguageChange} getTranslation={getTranslation} />
      </nav>
    </header>
    <main className="responsive small-padding">
      <div className="small-space m l"></div>

      { body }

      <div className="medium-space"></div>
    </main>
    <footer className="fill horizontal">
      <div className="vertical">
        <p>{getTranslation('license')} <a className="link" href="https://creativecommons.org/licenses/by-nc/4.0/">CC-BY-NC 4.0</a></p>
        <img src="by-nc.png" width="117" height="41" />
      </div>
      <div className="vertical">
        <a className="link" href="https://github.com/ericapkochig/ericapkochig.github.io/blob/main/PRIVACY.md" target="_blank">
          <p>{getTranslation('privacy_policy')}</p>
        </a>
      </div>
    </footer>
  </>
}


export default App;
