import { AnwersStateType } from "../App.types"

type DebugBarInput = {
  isDebug: boolean
  answersState: AnwersStateType
  currentSection: number
}

export default function DebugBar({ isDebug, answersState, currentSection }: DebugBarInput) {
  if (!isDebug) return <></>

  const answers_elements = Object.keys(answersState.question_answers).map(questionID => {

    const answers = answersState.question_answers[questionID].map(answerID => {
      return <code key={answerID} className="right-margin tiny-margin">{answerID}</code>
    })

    return <tr key={questionID}>
      <td className="min">
        <code>{questionID}</code>
      </td>
      <td>{answers}</td>
    </tr>
  })

  return (

    <nav className="m l left">
      <div className="vertical">
        <span className="left-align"><b>Section:</b> {currentSection}</span>
        <table>
          <thead>
            <tr>
              <th className="min">Q</th>
              <th>A</th>
            </tr>
          </thead>
          <tbody>
            { answers_elements }
          </tbody>
          {/* <tfoot>
            <tr>
              <th className="min">Footer</th>
              <th>Footer</th>
            </tr>
          </tfoot> */}
        </table>
      </div>

    </nav>

  )
}
