import { ReactElement } from "react"
import { getTranslationFn } from "../App"
import { SectionStateType } from "../App.types"

export type onClickStep = (index: number) => void;

type NavigationBarInput = {
  sectionState: SectionStateType
  maxSections: number
  isDebug: boolean
  getTranslation: getTranslationFn
  onClick?: onClickStep,
}

export default function StepsBar(input: NavigationBarInput) {
  let sections: ReactElement[] = []
  let curSection: ReactElement = <></>

  // We introduce an artificial section at the end: Feedback
  let sections_len = input.maxSections + 1;

  const onClickStep = (index: number) => {
    console.log(index)
    if (!input.onClick) return;

    input.onClick(index);
  }

  for (let i = 1 ; i <= sections_len ; i++ ) {
    if (i > 1) {
      sections.push(<hr key={i+'hr'} className="max"></hr>)
    }

    const text = i === sections_len
      ? input.getTranslation('web_navbar_step_feedback')
      : input.getTranslation('web_navbar_step_' + i);

    const isCompleted = i <= input.sectionState.locked;
    const isAvailable = i <= input.sectionState.locked + 1;
    const isLatest = i === input.sectionState.locked + 1;
    const isCurrent = i === input.sectionState.current;

    const btnStyle = 'circle small' + (!isLatest ? ' secondary' : '');

    sections.push(
      <div key={i} className="center-align">
        <button className={btnStyle} disabled={!isAvailable} onClick={() => onClickStep(i)}>
          { isCompleted && <i>done</i>}
          {!isCompleted && i}
        </button>
        <div className={'small-margin' + (isCurrent ? ' bold primary-text' : '')}>{ text }</div>
      </div>
    )

    if (isCurrent) {
      curSection = <div key={i} className="center-align">
        <button className={btnStyle} disabled={!isAvailable} onClick={() => onClickStep(i)}>
          { isCompleted && <i>done</i>}
          {!isCompleted && i}
        </button>
        <div className={'small-margin' + (isCurrent ? ' bold primary-text' : '')}>{ text }</div>
      </div>
    }
  }

  return <>
    <nav className="s max center-align"> { curSection } </nav>
    <nav className="m l"> { sections } </nav>
  </>
}
