export type AnwersStateType = {
  // Holds a dictionary of <QuestionID, AnswerIDs>
  question_answers: {
    [key: string]: string[]
  },
  // Holds a dictionary of <AnswerID, State>. State is true when selected, undefined when not (or key missing)
  answers_index: AnswerStateIndexType,
}

export type SectionStateType = {
  current: number,
  locked: number,
  feedback: FeedbackSectionEnum,
  feedbackReadAll: boolean,
}

export type AnswerStateIndexType = {
  [key: string]: boolean | undefined,
}


export const MULTIPLE_CHOICE = 'M'

export const LANGUAGES = ['es', 'en', 'pt']

export function getFormsRedirectURL(language: string): string {
  switch (language) {
    case 'es':
      return 'https://forms.office.com/Pages/ResponsePage.aspx?id=aykR84I-TkyCqajkA6QrEXJESMaf_URCjK-EDtEKv05UOU9TWFE3U1BBVlZaWFJWMTVVUUJJODNJRi4u&r4fc87dcf0f6a4ca4ae623121dcb31d6a='
    case 'pt':
      return 'https://forms.office.com/Pages/ResponsePage.aspx?id=aykR84I-TkyCqajkA6QrEXJESMaf_URCjK-EDtEKv05UREwzVDhHUkhDMzlJTTBPT0VQSTBRRVNHVC4u&r4fc87dcf0f6a4ca4ae623121dcb31d6a='
    case 'en':
    default:
      return 'https://forms.office.com/Pages/ResponsePage.aspx?id=aykR84I-TkyCqajkA6QrEXJESMaf_URCjK-EDtEKv05UMzBTQllONjdYUlZFMEw3WloxN0pTVE9MNy4u&r4fc87dcf0f6a4ca4ae623121dcb31d6a='
  }
}

export enum FeedbackSectionEnum {
  SCORES = 0,
  NEG = 1,
  POS = 2,
}
