type OnChangeCallback = (
  question_id: string,
  selectedValue: string,
  isMulti: boolean,
  checked: boolean,
) => void;

type QuestionInput = {
  values?: string[],
  question: QuestionType,
  onChange?: OnChangeCallback,
  isDebug: boolean,
  getTranslation: getTranslationFn
  sectionState: SectionStateType
  answersIndex: AnswerStateIndexType
}


export default function Question({ values, question, onChange, isDebug, getTranslation, sectionState, answersIndex } : QuestionInput) {
  const isMultiChoice = question.type === MULTIPLE_CHOICE

  let choices: ReactElement[] = []
  question.answers.forEach(answer => {

    let checked = false;
    if (values)
      checked = values.indexOf(answer.id) >= 0

    const debugID = isDebug ? <code className="right-margin small-margin">[{answer.id}]</code> : <></>
    const isReadOnly = sectionState.locked >= sectionState.current

    choices.push(
      <label key={ answer.id } className={isMultiChoice ? 'checkbox' : 'radio'}>
        <input
          value={answer.id}
          type={isMultiChoice ? 'checkbox' : 'radio'}
          name={ question.id }
          checked={checked}
          disabled={isReadOnly && !answersIndex[answer.id]}
          onChange={e => !isReadOnly && handleOnChange(e.target)}>
        </input>
        <span> { debugID } { getTranslation(t_answer_key(answer.id)) } </span>
      </label>
    )
  })

  const handleOnChange = (target: HTMLInputElement) => {
    if (!onChange) return;

    onChange(
      question.id,
      target.value,
      isMultiChoice,
      isMultiChoice ? target.checked : true
    );
  }

  const debugID = isDebug ? <code className="right-margin small-margin">[{question.id}]</code> : <></>

  return <fieldset id={question.id}>
    <span className="bold"> { debugID } { getTranslation(t_question_key(question.id)) } </span>
    <nav className="vertical">
      {/* <select value={value} onChange={e => handleOnChange(e.target)}> */}
        { choices }
      {/* </select> */}
    </nav>
  </fieldset>
}
