import { ReactElement } from "react";
import { AnwersStateType, FeedbackSectionEnum, getFormsRedirectURL, MULTIPLE_CHOICE, SectionStateType } from "../App.types";
import { AnswerID, AnswerModifierIndex, AnswerType, IngestedDataType, QuestionID } from "../ingest/ingest.types";
import { getTranslationFn } from "../App";
import { t_feedback_neg_dev, t_feedback_neg_did, t_feedback_neg_ped, t_feedback_pos_a, t_feedback_pos_a_bis, t_feedback_pos_b } from "../translation";
import { encodeAnswers } from "../utils/state";

export type FeedbackInput = {
  isDebug: boolean,
  answersState: AnwersStateType,
  sectionState: SectionStateType,
  data: IngestedDataType,
  getTranslation: getTranslationFn,
  goToFirstStepClicked: () => void,
  onFeedbackSectionChange: (target: number, hasMoreFeedback: boolean) => void,
  language: string,
}

export type FeedbackScore = {
  q: QuestionID,
  a: AnswerID,
  base: number,  // Base score (without mods)
  mods: number,  // Modifiers sum
  debug_find_answer: string, // Human friendly showcase
  debug_mods: string,
}

export default function Feedback({ isDebug, answersState, sectionState, data, getTranslation, goToFirstStepClicked, onFeedbackSectionChange, language }: FeedbackInput): ReactElement {
  const scores_arr: FeedbackScore[] = calculateScores(answersState, data);

  const base_score = scores_arr.reduce((sum, it) => sum + it.base, 0)
  const mods_score = scores_arr.reduce((sum, it) => sum + it.mods, 0)

  const divClass = 'vertical-margin medium-margin'

  // Feedback based on Score
  const match_feedback = data.feedback_score.find(it => base_score >= it.min && base_score <= it.max);
  let feedback_el = <></>
  if (!match_feedback) {
    console.log(`🔥 Unable to find a match feedback for a score of [${base_score}]`)
  }
  else {
    feedback_el = <>
      <div className={divClass}>
        { isDebug && <code className="right-margin small-margin">{match_feedback.key}</code> }
        <i className="small">check_small</i>
        { getTranslation(match_feedback.key) }
      </div>
    </>
  }

  // Feedback based on Mod. Score
  const match_mod_feedback = data.feedback_score_mods.find(it => mods_score >= it.min && mods_score <= it.max)
  let feedback_mod_el = <></>
  if (!match_mod_feedback) {
    console.log(`🔥 Unable to find a match feedback mods. for a score of [${mods_score}]`)
  }
  else {
    feedback_mod_el = <>
      <div className={divClass}>
        { isDebug && <code className="right-margin small-margin">{match_mod_feedback.key}</code> }
        <i className="small">check_small</i>
        { getTranslation(match_mod_feedback.key) }
      </div>
    </>
  }

  // Feedback based on flags
  let feedback_flags_neg: ReactElement[] = []
  let feedback_flags_neg_debug: ReactElement[] = []
  let feedback_flags_pos: ReactElement[] = []
  let feedback_flags_pos_debug: ReactElement[] = []

  let feedback_texts: string[] = []
  const separator = <div className="tiny-space"></div>

  Object.keys(data.feedback).forEach(answerID => {
    if (!answersState.answers_index[answerID]) return;
    const feedback_data = data.feedback[answerID];

    if (feedback_data.neg.dev) {
      let criteria_match: string | undefined = undefined;
      const length = feedback_data.neg.dev_criteria?.length || 0;

      for (let i = 0 ; i < length ; i++ ) {
        // @ts-ignore
        const check_answerID = feedback_data.neg.dev_criteria[i];
        if (answersState.answers_index[check_answerID]) {
          criteria_match = check_answerID;
          break;
        }
      }

      // Only show when criteria matches
      if (criteria_match) {
        const loc = t_feedback_neg_dev(answerID)
        const txt = getTranslation(loc)

        // De-duplicate texts that are the same
        if (feedback_texts.indexOf(txt) < 0) {
          feedback_texts.push(txt)

          feedback_flags_neg.push(
            <div key={answerID + 'negdev'} className={divClass}>
              {isDebug && <code className="right-margin small-margin">{answerID} neg dev ✅️ {criteria_match} - {loc}</code>}
              <i className="small">check_small</i>
              { txt }
            </div>
          )

          feedback_flags_neg.push(separator)
        }
        else {
          feedback_flags_neg_debug.push(<div key={answerID + 'negdev'} className={divClass}>
            🚫 <code>{answerID}</code> Neg. Dev. excluded. 💬 Text repeated<code>{txt}</code>
          </div>)
        }
      }
      else if (!criteria_match && isDebug) {
        feedback_flags_neg_debug.push(<div key={answerID + 'negdev'} className={divClass}>
          🚫 <code>{answerID}</code> Neg. Dev. excluded. Criteria not found <code>{feedback_data.neg.dev_criteria?.join(', ')}</code>
        </div>)
      }
    }

    if (feedback_data.neg.did) {
      const loc = t_feedback_neg_did(answerID)
      const txt = getTranslation(loc)

      // De-duplicate texts that are the same
      if (feedback_texts.indexOf(txt) < 0) {
        feedback_texts.push(txt)

        feedback_flags_neg.push(
          <div key={answerID + 'negdid'} className={divClass}>
            {isDebug && <code className="right-margin small-margin">{answerID} neg did - {loc}</code>}
            <i className="small">check_small</i>
            { txt }
          </div>
        )

        feedback_flags_neg.push(separator)
      }
      else {
        feedback_flags_neg_debug.push(<div key={answerID + 'negdid'} className={divClass}>
          🚫 <code>{answerID}</code> Neg. Did. excluded. 💬 Text repeated<code>{txt}</code>
        </div>)
      }
    }

    if (feedback_data.neg.ped) {
      const loc = t_feedback_neg_ped(answerID)
      const txt = getTranslation(loc)

      // De-duplicate texts that are the same
      if (feedback_texts.indexOf(txt) < 0) {
        feedback_texts.push(txt)

        feedback_flags_neg.push(
          <div key={answerID + 'negped'} className={divClass}>
            {isDebug && <code className="right-margin small-margin">{answerID} neg ped - {loc}</code>}
            <i className="small">check_small</i>
            { getTranslation(loc) }
          </div>
        )

        feedback_flags_neg.push(separator)
      }
      else {
        feedback_flags_neg_debug.push(<div key={answerID + 'negped'} className={divClass}>
          🚫 <code>{answerID}</code> Neg. Ped. excluded. 💬 Text repeated<code>{txt}</code>
        </div>)
      }
    }

    if (feedback_data.pos.a && feedback_data.pos.a_bis) {
      let criteria_match: string | undefined = undefined;
      const length = feedback_data.pos.a_criteria?.length || 0;

      for (let i = 0 ; i < length ; i++ ) {
        // @ts-ignore
        const check_answerID = feedback_data.pos.a_criteria[i];
        if (answersState.answers_index[check_answerID]) {
          criteria_match = check_answerID;
          break;
        }
      }

      // Show A, when criteria do *not* match
      if (!criteria_match) {
        const loc = t_feedback_pos_a(answerID)
        const txt = getTranslation(loc)

        // De-duplicate texts that are the same
        if (feedback_texts.indexOf(txt) < 0) {
          feedback_texts.push(txt)

          feedback_flags_pos.push(
            <div key={answerID + 'a_abis'} className={divClass}>
              {isDebug && <code className="right-margin small-margin">{answerID} pos ✅️ a 🚫 a_bis - {loc}</code>}
              <i className="small">check_small</i>
              { getTranslation(loc) }
            </div>
          )

          feedback_flags_pos.push(separator)
        }
        else {
          feedback_flags_neg_debug.push(<div key={answerID + 'a_abis'} className={divClass}>
            🚫 <code>{answerID}</code> pos ✅️ a 🚫 a_bis. 💬 Text repeated<code>{txt}</code>
          </div>)
        }
      }
      // Show B, when criteria *match*
      else {
        const loc = t_feedback_pos_a_bis(answerID)
        const txt = getTranslation(loc)

        // De-duplicate texts that are the same
        if (feedback_texts.indexOf(txt) < 0) {
          feedback_texts.push(txt)

          feedback_flags_pos.push(
            <div key={answerID + 'a_abis'} className={divClass}>
              {isDebug && <code className="right-margin small-margin">{answerID} pos 🚫 a ✅️ a_bis ({criteria_match}) - {loc}</code>}
              <i className="small">check_small</i>
              { getTranslation(loc) }
            </div>
          )

          feedback_flags_pos.push(separator)
        }
        else {
          feedback_flags_neg_debug.push(<div key={answerID + 'a_abis'} className={divClass}>
            🚫 <code>{answerID}</code> pos 🚫 a ✅️ a_bis ({criteria_match}). 💬 Text repeated<code>{txt}</code>
          </div>)
        }
      }
    }
    else if (feedback_data.pos.a) {
      const loc = t_feedback_pos_a(answerID)
      const txt = getTranslation(loc)

      // De-duplicate texts that are the same
      if (feedback_texts.indexOf(txt) < 0) {
        feedback_texts.push(txt)

        feedback_flags_pos.push(
          <div key={answerID + 'a'} className={divClass}>
            {isDebug && <code className="right-margin small-margin">{answerID} pos a - {loc}</code>}
            <i className="small">check_small</i>
            { getTranslation(loc) }
          </div>
        )

        feedback_flags_pos.push(separator)
      }
      else {
        feedback_flags_neg_debug.push(<div key={answerID + 'a'} className={divClass}>
          🚫 <code>{answerID}</code> pos a. 💬 Text repeated<code>{txt}</code>
        </div>)
      }
    }

    if (feedback_data.pos.b) {
      const loc = t_feedback_pos_b(answerID)
      const txt = getTranslation(loc)

      // De-duplicate texts that are the same
      if (feedback_texts.indexOf(txt) < 0) {
        feedback_texts.push(txt)

        feedback_flags_pos.push(
          <div key={answerID + 'b'} className={divClass}>
            {isDebug && <code className="right-margin small-margin">{answerID} pos b - {loc}</code>}
            <i className="small">check_small</i>
            { getTranslation(loc) }
          </div>
        )

        feedback_flags_pos.push(separator)
      }
      else {
        feedback_flags_neg_debug.push(<div key={answerID + 'b'} className={divClass}>
          🚫 <code>{answerID}</code> pos b. 💬 Text repeated<code>{txt}</code>
        </div>)
      }
    }
  })

  // Remove last {separator} element
  if (feedback_flags_neg.length > 0) {
    feedback_flags_neg = feedback_flags_neg.slice(0, feedback_flags_neg.length - 1)
  }
  // Remove last {separator} element
  if (feedback_flags_pos.length > 0) {
    feedback_flags_pos = feedback_flags_pos.slice(0, feedback_flags_pos.length - 1)
  }

  // -----------------------------------------------------------------------------------------
  // Actions

  function onSubmitScore() {
    const responses_encoded = encodeAnswers(answersState);
    const url = getFormsRedirectURL(language);

    window.open(url + responses_encoded, '_blank');
  }

  function onNextFeedback() {
    onFeedbackSectionChange(sectionState.feedback + 1, hasMoreFeedback)
  }

  function onPrevFeedback() {
    if (sectionState.feedback === FeedbackSectionEnum.NEG) {
      onFeedbackSectionChange(FeedbackSectionEnum.SCORES, hasMoreFeedback);
      return;
    }

    onFeedbackSectionChange(feedback_flags_neg.length === 0
      ? FeedbackSectionEnum.SCORES
      : FeedbackSectionEnum.NEG,
    hasMoreFeedback)
  }

  let content = <></>
  let hasMoreFeedback = true;

  switch (sectionState.feedback) {
    case FeedbackSectionEnum.SCORES:
      content = <>
        <fieldset className="small-padding">
          {feedback_el}
          {separator}
          {feedback_mod_el}
        </fieldset>
      </>

      if (feedback_flags_neg.length === 0 && feedback_flags_pos.length === 0) {
        hasMoreFeedback = false;
      }

      break;

    // @ts-ignore
    case FeedbackSectionEnum.NEG:
      if (feedback_flags_neg.length > 0) {
        content = <>
          <fieldset className="small-padding">
            {feedback_flags_neg}
            {isDebug && feedback_flags_neg_debug.length > 0 && <fieldset>{feedback_flags_neg_debug}</fieldset>}
          </fieldset>
        </>

        if (feedback_flags_pos.length === 0) {
          hasMoreFeedback = false;
        }

        break;
      }

    case FeedbackSectionEnum.POS:
      content = <>
        <fieldset className="small-padding">
          {feedback_flags_pos}
          {isDebug && feedback_flags_pos_debug.length > 0 && <fieldset>{feedback_flags_pos_debug}</fieldset>}
        </fieldset>
      </>

      hasMoreFeedback = false;
      break;
  }

  let buttonsMobile: ReactElement[] = []
  let buttons: ReactElement[] = []

  // If we have more feedback to show, and hans't been read entirely (yet), only present a single option: move forward
  if (hasMoreFeedback && !sectionState.feedbackReadAll) {
    buttons.push(
      <button key='next' className="large right-round" onClick={onNextFeedback}>
        { getTranslation('web_feedback_next') }
        <i>chevron_right</i>
      </button>)

    buttonsMobile.push(
      <button key='next' className="s12 large" onClick={onNextFeedback}>
        { getTranslation('web_feedback_next') }
        <i>chevron_right</i>
      </button>)
  }
  else {
    buttons.push(
      <button key='first_step' className="large border secondary-border secondary-text" onClick={goToFirstStepClicked}>
        <i>home</i>
        { getTranslation('web_feedback_goto_first_step') }
      </button>)

    if (sectionState.feedback !== FeedbackSectionEnum.SCORES || hasMoreFeedback) {
      buttons.push(
        <button key='prev' className="large border secondary-border secondary-text left-round" onClick={onPrevFeedback} disabled={sectionState.feedback === 0}>
          <i>chevron_left</i>
          { getTranslation('web_feedback_prev') }
        </button>)
    }

    if (hasMoreFeedback) {
      buttons.push(
        <button key='next' className="large right-round" onClick={onNextFeedback}>
          { getTranslation('web_feedback_next') }
          <i>chevron_right</i>
        </button>)
    }
    else {
      buttons.push(
        <button key='submit' className="large right-round" onClick={onSubmitScore}>
          <i>open_in_new</i>
          { getTranslation('web_feedback_goto_ms_forms') }
        </button>)
    }

    // ------------------------------------------------------------------------
    // Mobile buttons - order is different

    if (hasMoreFeedback) {
      buttonsMobile.push(
        <button key='next' className="s12 large" onClick={onNextFeedback}>
          { getTranslation('web_feedback_next') }
          <i>chevron_right</i>
        </button>)
    }
    else {
      buttonsMobile.push(
        <button key='submit' className="s12 large" onClick={onSubmitScore}>
          <i>open_in_new</i>
          { getTranslation('web_feedback_goto_ms_forms') }
        </button>)
    }

    if (sectionState.feedback !== FeedbackSectionEnum.SCORES || hasMoreFeedback) {
      buttonsMobile.push(
        <button key='prev' className="s12 large border secondary-border secondary-text" onClick={onPrevFeedback} disabled={sectionState.feedback === 0}>
          <i>chevron_left</i>
          { getTranslation('web_feedback_prev') }
        </button>)
    }

    buttonsMobile.push(
      <button key='first_step' className="s12 large border secondary-border secondary-text" onClick={goToFirstStepClicked}>
        <i>home</i>
        { getTranslation('web_feedback_goto_first_step') }
      </button>)
  }

  return <>
    <h5 className="primary-text">{ getTranslation('web_feedback_title') }</h5>

    { content }

    {/* Mobile view */}
    <div className="s grid">
      { buttonsMobile }
    </div>

    {/* Desktop view */}
    <nav className="m l left-align large-space">
      { buttons }
    </nav>

    { /* We add debug information to the end of the report.
         Only shows if the QueryParam 'debug' is present*/ }
    { getDebugInfo({isDebug, scores_arr, base_score, mods_score}) }
  </>
}

function calculateScores(answersState: AnwersStateType, data: any): FeedbackScore[] {
  let scores_arr: FeedbackScore[] = []

  Object.keys(answersState.question_answers).forEach(questionID => {
    const answers_arr: AnswerID[] = answersState.question_answers[questionID];
    const question_data = (data as IngestedDataType).questions.find(it => it.id === questionID)

    if (answers_arr.length === 0) {
      console.error(`Calculation Q [${questionID}] has no answers`)
      return
    }

    if (!question_data) {
      console.error(`Calculation Q [${questionID}] data not found`)
      return;
    }

    let score = {
      q: questionID,
      a: '',
      base: 0,
      mods: 0,
      debug_find_answer: '',
      debug_mods: '',
    }

    // ============================================================================================================
    // Multiple choice
    if (question_data.type === MULTIPLE_CHOICE) {
      score.debug_find_answer += 'Multiple-choice. '

      // Find the answer with the highest base score (or the first one)
      let chosen_answer: AnswerType
      for (let i = 0 ; i < answers_arr.length ; i++ ) {
        const answerID = answers_arr[i];
        let answer_data = (question_data.answers as AnswerType[]).find(it => it.id === answerID)

        if (!answer_data) {
          console.error(`Calculation Q. [${questionID}] A. [${answerID}] data not found`)
          score.debug_find_answer += `🔥 Answer [${answerID}] data not found`
          return
        }

        if (i === 0) {
          chosen_answer = answer_data
          score.debug_find_answer += ` ✅️ 1st [${answer_data.id}] value [${answer_data.value || 0}]. `
        }
        // @ts-ignore
        else if ((answer_data.value || 0) > (chosen_answer.value || 0) ) {
          chosen_answer = answer_data
          score.debug_find_answer += ` ✅️ High score [${answer_data.id}] value [${answer_data.value || 0}]. `
        }
        // Ignored
        else {
          // No-Op
          score.debug_find_answer += ` 🚫 Skip [${answer_data.id}] value [${answer_data.value || 0}]. `
        }
      }

      // @ts-ignore
      score.debug_find_answer += `🏅 Selected [${chosen_answer.id}]`

      // @ts-ignore
      score.a = chosen_answer.id;
      // @ts-ignore
      score.base = chosen_answer.value || 0;
      // @ts-ignore
      const mod_res = calculateModifiers(chosen_answer.id, answersState, data)
      score.mods = mod_res.mod
      score.debug_mods += mod_res.debug
    }
    // ============================================================================================================
    // Single choice
    else {
      if (answers_arr.length > 1) {
        console.error(`Calculation Q. [${questionID}] is single-choice, but multiple answers are selected ${answers_arr}`)
        return;
      }
      const answerID = answers_arr[0];
      let answer_data = (question_data.answers as AnswerType[]).find(it => it.id === answerID)

      if (!answer_data) {
        console.error(`Calculation Q. [${questionID}] A. [${answerID}] data not found`)
        return
      }

      score.debug_find_answer += `Single-choice 🏅 Selected [${answerID}]`

      score.a = answerID;
      score.base = answer_data.value || 0;

      const mod_res = calculateModifiers(answerID, answersState, data)
      score.mods = mod_res.mod
      score.debug_mods += mod_res.debug
    }

    scores_arr.push(score)
  })

  return scores_arr;
}

function calculateModifiers(answerID: AnswerID, answersState: AnwersStateType, data: IngestedDataType): { mod: number, debug: string } {
  let result = {
    mod: 0,
    debug: '',
  }

  const modifiers_data = (data.answer_modifier_index as AnswerModifierIndex)[answerID]
  if (!modifiers_data) {
    result.debug += `No mods. [${answerID}]. `
    return result;
  }

  Object.keys(modifiers_data).forEach(answerdID_mod => {
    const mod_value = modifiers_data[answerdID_mod];

    if (answersState.answers_index[answerdID_mod]) {
      result.debug += `✅️ ${answerdID_mod} = ${mod_value} `
      result.mod += mod_value
    }
    else {
      result.debug += `🚫 ${answerdID_mod} `
    }
  })

  return result;
}

type getDebugInfoInput = {
  isDebug: boolean,
  scores_arr: FeedbackScore[],
  base_score: number,
  mods_score: number,
}

function getDebugInfo({ isDebug, scores_arr, base_score, mods_score }: getDebugInfoInput) {
  if (!isDebug) return <></>

  return <>
    <div className="medium-space"></div>
    <fieldset>
      <h5>Score calculation</h5>
      <div className="small-space"></div>

      <table className="no-space">
        <thead>
          <tr>
            <th className="min"></th>
            <th>Score</th>
          </tr>
        </thead>
        <tbody>
          <tr>
            <td className="min">Base</td>
            <td><code>{base_score}</code></td>
          </tr>
          <tr>
            <td className="min">Mods</td>
            <td><code>{mods_score}</code></td>
          </tr>
          <tr>
            <td className="min">Total</td>
            <td><code>{base_score + mods_score}</code></td>
          </tr>
        </tbody>
      </table>

      <div className="small-space"></div>
      <textarea name="debug_score" className="responsive large-height" value={ JSON.stringify(scores_arr, null, 2) } readOnly></textarea>
    </fieldset>
  </>
}
