import { AnwersStateType } from "../App.types";

const Q_A_SEPARATOR = ':'
const Q_Q_SEPARATOR = '|'
const A_A_SEPARATOR = ','

export function encodeAnswers(answersState: AnwersStateType): string {
  let responses = '';
  Object.keys(answersState.question_answers).forEach((questionID, idx) => {
    if (idx > 0) {
      responses += Q_Q_SEPARATOR
    }

    responses += questionID
      + Q_A_SEPARATOR
      + answersState.question_answers[questionID].join(A_A_SEPARATOR)
  })

  const responses_encoded = encodeURIComponent(responses);

  return responses_encoded;
}
