import { ReactElement } from "react"
import { getTranslationFn } from "../App"
import { IngestedDataType } from "../ingest/ingest.types"
import { LANGUAGES } from "../App.types"

export type WelcomeInput = {
  getTranslation: getTranslationFn
  data: IngestedDataType
  language: string,
  onClick: () => void
  onLangSelected: (language: string) => void,
}


export default function Welcome ({ getTranslation, data, onClick, language, onLangSelected }: WelcomeInput) {

  let sections: ReactElement[] = []

  for (let i = 1 ; ; i++ ) {
    if (!data.translation['welcome_txt_' + i]) {
      break;
    }

    if (i > 1) {
      sections.push(<div className="space"></div>)
      sections.push(<hr />)
      sections.push(<div className="space"></div>)
    }

    const translationSplit = getTranslation('welcome_txt_' + i).split('$$')
    const elements: ReactElement[] = []

    for (let i = 0 ; i < translationSplit.length ; i ++ ) {
      elements.push(<p>{translationSplit[i]}</p>)
    }

    sections.push(<>{ elements }</>)
  }

  const langButtons: ReactElement[] = []
  const langButtonsMobile: ReactElement[] = []

  LANGUAGES.forEach(lang => {
    langButtons.push(<button
      key={lang}
      className={lang === language ? 'large small-round' : 'large small-round border'}
      onClick={ () => onLangSelected(lang) }
      >
        { `${getTranslation('lang_' + lang)} (${lang.toUpperCase()})` }
      </button>)

    langButtonsMobile.push(<button
      key={lang}
      className={lang === language ? 's12 large' : 's12 large border secondary-border secondary-text'}
      onClick={ () => onLangSelected(lang) }
      >
        <p>{ getTranslation('lang_' + lang) }</p>
      </button>)
  })

  return <>
    <nav className="center-align large-space">
      <h6 className="">{ getTranslation('welcome_language_selection') }</h6>
    </nav>

    {/* Mobile view */}
    <div className="s grid">
      { langButtonsMobile }
    </div>

    {/* Desktop View */}
    <nav className="m l center-align large-space">
      { langButtons }
    </nav>

    <h5 className="vertical-padding medium-padding">{getTranslation('welcome_sub-title')}</h5>

    <div className="vertical">
      <p>{getTranslation('welcome_txt_1a')}</p>
      <p>{getTranslation('welcome_txt_1b')}</p>
      <ul className="top-margin no-margin">
        <li>{getTranslation('welcome_txt_1d1')}</li>
        <li>{getTranslation('welcome_txt_1d2')}</li>
        <li>{getTranslation('welcome_txt_1d3')}</li>
        <li>{getTranslation('welcome_txt_1d4')}</li>
      </ul>
      <p>{getTranslation('welcome_txt_1e')}</p>

      <hr className="vertical-margin large-margin" />

      <p className="bold">{getTranslation('welcome_txt_2a')}</p>
      <p>{getTranslation('welcome_txt_2b')}</p>
      <ul className="top-margin no-margin">
        <li>{getTranslation('welcome_txt_2c1')}</li>
        <li>{getTranslation('welcome_txt_2c2')}</li>
        <li>{getTranslation('welcome_txt_2c3')}</li>
      </ul>
      <p>{getTranslation('welcome_txt_2d')}</p>
      <p>{getTranslation('welcome_txt_2e')}</p>

      <hr className="vertical-margin large-margin" />

      <p className="bold">{getTranslation('welcome_txt_3a')}</p>
      <p>{getTranslation('welcome_txt_3b')}</p>
      <ul className="top-margin no-margin">
        <li>{getTranslation('welcome_txt_3c1')}</li>
        <li>{getTranslation('welcome_txt_3c2')}</li>
        <li>{getTranslation('welcome_txt_3c3')}</li>
      </ul>
      <p>{getTranslation('welcome_txt_3d')}</p>
    </div>

    <div className="space"></div>

    {/* Mobile */}
    <div className="s grid">
      <button className="s12 large small-round" onClick={onClick}>
        { getTranslation('welcome_btn_begin') }
      </button>
    </div>

    {/* Desktop */}
    <nav className="m l center-align large-space">
      <button className="responsive large small-round" onClick={onClick}>
        { getTranslation('welcome_btn_begin') }
      </button>
    </nav>
  </>
}
